css:
/* ==== INTERFACE ====
方向：自然摄影编辑风；默认页以清爽纸白、森林墨色与克制的年轮线条承载公式和数据，开篇用左文右图的湖畔摄影与杂志式标题形成安静但清晰的课堂画面。
token --bg：页面底色。
token --text：正文与主要数据色。
token --font-sans：正文与控件字体。
token --muted：次要说明与图注色。
token --focus：键盘焦点色。
token --growth：增长数据与趋势强调色。
token --principal：本金与基准量色。
token --current：当前步骤或当前交互强调色。
token --fs-h1/--fs-h2/--fs-lead/--fs-body/--fs-sec/--fs-label/--fs-tick：投影字阶。
token --sp-1/--sp-2/--sp-3/--sp-4/--sp-5/--sp-6：通用间距。
class .nt-title：杂志式页标题。
class .nt-kicker：栏目眉题。
class .nt-lead：导语。
class .nt-formula：核心公式排版。
class .nt-number：关键数字。
class .nt-note：说明或图注。
class .nt-data-table：n=0..5 数据表。
class .nt-growth-chart：增长图表视觉语言。
class .nt-controls：课堂交互控件组。
variant opening：开篇摄影外观；右侧使用 photo.jpg，左侧由多层底色保证标题对比，适合主要文字位于左半区。
默认：不设 data-variant；无摄影，仅使用浅色纸面与极淡自然光背景。
品牌：无。
==== /INTERFACE ==== */

:root {
  --bg: #f4f5f0;
  --text: #17211c;
  --font-sans: "Noto Sans CJK SC", "Noto Sans", "WenQuanYi Zen Hei", sans-serif;
  --font-serif: "Noto Serif CJK SC", "Noto Serif", "Noto Serif Display", serif;
  --font-mono: "JetBrains Mono", "Noto Sans Mono", monospace;

  --muted: #59645d;
  --focus: #b85f22;
  --growth: #2f6b4f;
  --growth-soft: #dce8df;
  --principal: #2f5960;
  --principal-soft: #dbe7e8;
  --current: #c56b2b;
  --current-soft: #f3dfcc;
  --rule: #aeb9b1;
  --rule-strong: #68776d;
  --paper: #fbfcf8;
  --ink-reverse: #f7f8f3;
  --muted-reverse: #d8ddd8;

  --fs-h1: 76px;
  --fs-h2: 46px;
  --fs-lead: 27px;
  --fs-body: 21px;
  --fs-sec: 18px;
  --fs-label: 16px;
  --fs-tick: 14px;

  --sp-1: 8px;
  --sp-2: 14px;
  --sp-3: 22px;
  --sp-4: 34px;
  --sp-5: 52px;
  --sp-6: 76px;

  --radius-sm: 5px;
  --radius-md: 12px;
  --photo-source: url("photo.jpg");
}

html[data-variant="opening"] {
  --bg: #e9ece6;
  --text: #152019;
  --muted: #4e5b52;
  --rule: #98a49b;
}

#stage {
  color: var(--text);
  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 82% 12%, rgb(255 255 255 / 0.58), transparent 25%),
    linear-gradient(112deg, rgb(255 255 255 / 0.34), transparent 38%);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.52;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

html[data-variant="opening"] #stage {
  background-color: var(--bg);
  background-image:
    linear-gradient(90deg, #edf0e9 0%, #edf0e9 42%, rgb(237 240 233 / 0.97) 47%, rgb(237 240 233 / 0.7) 53%, rgb(237 240 233 / 0.08) 65%),
    linear-gradient(180deg, rgb(9 17 12 / 0.02) 0%, transparent 55%, rgb(9 17 12 / 0.2) 100%),
    var(--photo-source);
  background-position: center, center, right center;
  background-repeat: no-repeat;
  background-size: 100% 100%, 100% 100%, 52% auto;
}

.nt-title {
  max-width: 13ch;
  margin: 0;
  color: var(--text);
  font-family: var(--font-serif);
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.035em;
  text-wrap: balance;
}

.nt-title strong,
.nt-title em {
  color: var(--growth);
  font-style: normal;
  font-weight: 700;
}

html[data-variant="opening"] .nt-title {
  max-width: 10.5ch;
  font-size: 84px;
  line-height: 1.04;
}

.nt-kicker {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 var(--sp-3);
  color: var(--growth);
  font-size: var(--fs-label);
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.nt-kicker::before {
  width: 34px;
  height: 2px;
  flex: 0 0 auto;
  background: currentColor;
  content: "";
}

.nt-lead {
  max-width: 32em;
  margin: var(--sp-3) 0 0;
  color: var(--muted);
  font-size: var(--fs-lead);
  font-weight: 500;
  line-height: 1.48;
}

.nt-body {
  color: var(--text);
  font-size: var(--fs-body);
  line-height: 1.58;
}

.nt-section-title {
  margin: 0;
  color: var(--text);
  font-family: var(--font-serif);
  font-size: var(--fs-h2);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.nt-formula {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.18em;
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 42px;
  font-weight: 700;
  line-height: 1.3;
  font-variant-numeric: tabular-nums lining-nums;
  letter-spacing: -0.025em;
}

.nt-formula .nt-principal,
.nt-number.nt-principal {
  color: var(--principal);
}

.nt-formula .nt-growth,
.nt-number.nt-growth {
  color: var(--growth);
}

.nt-formula .nt-current,
.nt-number.nt-current {
  color: var(--current);
}

.nt-number {
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 1.2em;
  font-weight: 700;
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-equation-step {
  border-inline-start: 5px solid var(--growth);
  padding-inline-start: var(--sp-3);
}

.nt-note {
  max-width: 46em;
  margin: 0;
  color: var(--muted);
  font-size: var(--fs-sec);
  line-height: 1.52;
}

.nt-caption {
  color: var(--muted);
  font-size: var(--fs-label);
  line-height: 1.45;
}

.nt-rule-label {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-size: var(--fs-label);
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: 0.04em;
}

.nt-rule-label::after {
  width: 54px;
  height: 1px;
  background: var(--rule-strong);
  content: "";
}

.nt-data-table {
  border-collapse: collapse;
  color: var(--text);
  font-size: var(--fs-body);
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-data-table th,
.nt-data-table td {
  padding: 15px 22px;
  border-bottom: 1px solid var(--rule);
  text-align: right;
  vertical-align: middle;
}

.nt-data-table th {
  color: var(--muted);
  font-size: var(--fs-label);
  font-weight: 700;
  letter-spacing: 0.035em;
}

.nt-data-table th:first-child,
.nt-data-table td:first-child {
  padding-inline-start: 0;
  text-align: left;
}

.nt-data-table tbody tr:last-child td {
  border-bottom-color: var(--rule-strong);
}

.nt-data-table tr[aria-current="true"] td,
.nt-data-table tr.is-current td {
  color: #7f3d12;
  background: var(--current-soft);
  font-weight: 700;
}

.nt-growth-chart {
  color: var(--text);
  font-family: var(--font-sans);
}

.nt-growth-chart .nt-axis {
  stroke: var(--rule-strong);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.nt-growth-chart .nt-grid {
  stroke: var(--rule);
  stroke-width: 1;
  stroke-dasharray: 3 7;
  vector-effect: non-scaling-stroke;
}

.nt-growth-chart .nt-line {
  fill: none;
  stroke: var(--growth);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.nt-growth-chart .nt-area {
  fill: var(--growth-soft);
  opacity: 0.76;
}

.nt-growth-chart .nt-point {
  fill: var(--paper);
  stroke: var(--growth);
  stroke-width: 4;
  vector-effect: non-scaling-stroke;
}

.nt-growth-chart .nt-point.is-current,
.nt-growth-chart [aria-current="true"].nt-point {
  fill: var(--current);
  stroke: var(--paper);
  stroke-width: 5;
}

.nt-growth-chart text,
.nt-tick {
  fill: var(--muted);
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-2) var(--sp-3);
  color: var(--muted);
  font-size: var(--fs-label);
  line-height: 1.4;
}

.nt-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 9px;
}

.nt-swatch {
  width: 18px;
  height: 5px;
  flex: 0 0 auto;
  border-radius: 999px;
  background: var(--growth);
}

.nt-swatch.nt-principal {
  background: var(--principal);
}

.nt-swatch.nt-current {
  background: var(--current);
}

.nt-controls {
  --surface: rgb(251 252 248 / 0.94);
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid rgb(104 119 109 / 0.55);
  border-radius: var(--radius-md);
  background: var(--surface);
  box-shadow: 0 12px 30px rgb(23 33 28 / 0.11);
  color: var(--text);
  backdrop-filter: blur(8px);
}

.nt-controls button,
.nt-button {
  min-height: 48px;
  padding: 10px 18px;
  border: 1px solid var(--rule-strong);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text);
  font: 700 var(--fs-label)/1.35 var(--font-sans);
  cursor: pointer;
}

.nt-controls button:hover,
.nt-button:hover {
  border-color: var(--growth);
  background: var(--growth-soft);
}

.nt-controls button[aria-pressed="true"],
.nt-controls button.is-current,
.nt-button.is-current {
  border-color: var(--current);
  background: var(--current-soft);
  color: #71350f;
}

.nt-controls label,
.nt-control-label {
  color: var(--muted);
  font-size: var(--fs-label);
  font-weight: 700;
  line-height: 1.35;
}

.nt-controls input[type="range"] {
  accent-color: var(--current);
}

.nt-controls button:focus-visible,
.nt-button:focus-visible,
.nt-controls input:focus-visible,
.nt-controls select:focus-visible,
.nt-controls a:focus-visible {
  outline: 4px solid color-mix(in srgb, var(--focus) 72%, white);
  outline-offset: 3px;
}

.nt-emphasis {
  color: var(--growth);
  font-weight: 700;
}

.nt-principal-band {
  border-inline-start: 8px solid var(--principal);
  background: var(--principal-soft);
  color: var(--text);
}

.nt-growth-band {
  border-inline-start: 8px solid var(--growth);
  background: var(--growth-soft);
  color: var(--text);
}

.nt-current-band {
  border-inline-start: 8px solid var(--current);
  background: var(--current-soft);
  color: #64300f;
}

@media (prefers-reduced-motion: reduce) {
  .nt-controls *,
  .nt-growth-chart * {
    scroll-behavior: auto;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
